def pancake_sort(arr):
    def flip(sub_arr, k):
        return sub_arr[:k][::-1] + sub_arr[k:]

    def find_max_index(sub_arr, n):
        max_idx = 0
        for i in range(1, n):
            if sub_arr[i] > sub_arr[max_idx]:
                max_idx = i
        return max_idx

    n = len(arr)
    for size in range(n, 1, -1):
        max_idx = find_max_index(arr, size)
        if max_idx != size - 1:
            if max_idx != 0:
                arr = flip(arr, max_idx + 1)
            arr = flip(arr, size)
    return arr
```

