def newman_prime(n):
    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    primes = []
    count = 1
    while len(primes) < n:
        if is_prime(count):
            primes.append(count)
        count += 1

    return primes[2]  # Return the 3rd Newman–Shanks–Williams prime number
